const ar=[
{title:'ألواح PVC في البرازيل: إيقاف رمز مخزون قديم | Luvie',heading:'ألواح PVC في البرازيل: استبدل المرجع المتوقف دون تغيير سجل الطلبات',description:'أوقف رمز ألواح PVC مع الحفاظ على الطلبات والمرتجعات وهوية المنتج. افصل اقتراح البديل عن إثبات التكافؤ.',lead:'يمكن للموزع إيقاف مجموعة ألواح PVC مع الاحتفاظ بالسجلات اللازمة لخدمة المشترين السابقين. تظهر المشكلة عندما يعامل نظام البيع البديل كأنه المنتج نفسه: تعرض الفواتير القديمة أبعاداً جديدة، أو يستلم العميل وصلة مختلفة، أو يُسجل المرتجع على مخزون لم يلبّ الطلب الأصلي. بالنسبة للموزع البرازيلي، نقل العمل إلى رمز جديد هو تسليم منظم بين سجلين، وليس مجرد تغيير صورة في إعلان قائم.',answer:'احتفظ بالمرجع المتوقف ومواصفاته التاريخية دون تغيير. أنشئ بديلاً ذا هوية مستقلة عند الحاجة، واربط السجلين بعلاقة صريحة، وراجع الطلبات المفتوحة قبل تحويل الاستفسارات الجديدة. لا تصف البديل بأنه قابل للتبادل قبل فحص الأبعاد والوصلة والتشطيب والاستخدام ذات الصلة.',sections:[['افصل الإيقاف عن الحذف','سجل سبب إيقاف المرجع ومن أكد حالة المورد. ميز بين الإيقاف الدائم وانقطاع التوريد المؤقت وقرارك المحلي بعدم تخزين المنتج. احفظ رمز المورد الأصلي ورمز المخزون المحلي والمواصفة المعتمدة ووحدة البيع والصور مع تواريخ مراجعتها. يجب أن تستمر الفواتير وسجلات الشحن القديمة في تعريف ما اشتراه العميل فعلياً. تؤكد إرشادات GS1 بشأن عدم إعادة استخدام GTIN أهمية الحفاظ على هوية المنتج، لكن رمز المستودع الداخلي ليس تلقائياً GTIN. إذا استخدمت معرفات GS1، فطبق قواعد تخصيصها بدلاً من نقل رقم متوقف إلى منتج مختلف لمجرد التسهيل.'],['قارن البديل قبل التوصية به','أنشئ مقارنة بين المرجع القديم والمقترح. تحقق من الأبعاد والتغطية الفعلية وشكل الوصلة والحليات المتوافقة ومعرف التشطيب والاستخدام المقصود عبر سجلات المورد الحالية. تشابه الاسم التسويقي لا يثبت إمكان جمع مقطعين في تركيب واحد. إذا كانت معلومة مجهولة، فسجلها كسؤال مفتوح بدلاً من نسخ المواصفة السابقة. حدد هل العلاقة تكافؤ لاستخدام محدد أم بديل يحتاج موافقة أم مجرد خيار آخر. سجل من اعتمد الوصف والأدلة التي راجعها. لا تعد بأن تشطيباً من إنتاج جديد سيطابق تركيباً قديماً دون فرق ظاهر.'],['عالج الطلب القائم قبل تغيير واجهة البيع','احصر الطلبات غير المنفذة وعروض الأسعار المفتوحة والعبوات المحجوزة والعينات لدى العملاء والمرتجعات المتوقعة. اطلب من مسؤول الحساب تحديد ما إذا كان يمكن تنفيذ كل التزام كما عُرض أو يحتاج تغييراً موثقاً يقبله المشتري. اجعل المخزون القديم المتبقي ظاهراً للموظفين المختصين دون الإيحاء بإمكان إعادة توريده بلا حدود. وضح حالة التوفر الفعلية في صفحة المنتج البرتغالية وقدم بديلاً موصوفاً بوضوح عند ملاءمته. لا تحول صفحة قديمة مفصلة بصمت إلى نموذج آخر مع إبقاء ادعاءاتها الفنية. راجع المواصفات القابلة للتنزيل ورسائل المبيعات مع الإعلان كي لا تبقى نسخ متناقضة متداولة.'],['اختبر الانتقال بحالات تشغيلية','قبل إغلاق التغيير، اطلب من الموظفين البحث عن فاتورة قديمة ومحاكاة مرتجع وإعداد عرض جديد للبديل. يجب أن تحافظ كل مهمة على هوية المنتج ووحدة البيع الصحيحتين. تحقق من أن مسح الرمز لا يخصص مخزون البديل لطلب يشترط المنتج المتوقف دون تعديل معتمد. حدد مسؤولاً للعينات القديمة والمطبوعات؛ علّمها أو اسحبها من البيع النشط مع حفظ الأرشيف اللازم. عين موعداً لمراجعة المخزون المتبقي والتزامات العملاء غير المحسومة. الهدف انتقال تجاري واضح، وليس كتالوجاً أنظف يخفي معلومات الخدمة والمساءلة.']],checklist:['حفظ هوية المنتج القديم ومواصفاته التاريخية.','دعم علاقة البديل بمقارنة فنية موثقة.','مراجعة الطلبات والعروض والمرتجعات والمخزون المتبقي.','فحص الصفحات البرتغالية وحالات التشغيل معاً.'],faq:[['هل نعيد استخدام الرمز القديم للوح جديد مشابه؟','تجنب الكتابة فوق السجل التاريخي. استخدم سجلاً مستقلاً عند الحاجة ورابطاً واضحاً للبديل. إذا كان المعرف GTIN، فاتبع قواعد GS1 للتخصيص وعدم إعادة الاستخدام.'],['هل يجب حذف كل صفحة منتج متوقف فوراً؟','ليس بالضرورة. قد يحتاج العملاء السابقون مواصفاته. احتفظ بالمعلومات التاريخية المفيدة مع توضيح حالتها وفصلها عن العرض المتاح للطلبات الجديدة.']],closing:'أرسل إلى Luvie مرجع PVC المتوقف والبديل المقترح. اطلب مقارنة حديثة للهوية والوصلة والتعبئة قبل تعديل الكتالوج البرازيلي أو قبول طلبات البديل.'},
{title:'ألواح WPC للإمارات: مقارنة عملة ووحدة العروض | Luvie',heading:'ألواح WPC للإمارات: قارن عروض الأسعار على أساس معلن واحد',description:'وحّد مقارنة عروض WPC حسب العملة ووحدة البيع والتغطية الفعلية ونطاق التسليم دون اختلاق تكاليف نهائية.',lead:'قد يُسعّر عرض WPC باللوح بعملة معينة وآخر بالعبوة بعملة أخرى. وقد يعرض ثالث سعراً بالمتر المربع دون توضيح إن كان يقصد المساحة الاسمية أو التغطية الفعلية بعد التركيب. لذلك ليس أصغر رقم ظاهر بالضرورة أقل عرض قابل للمقارنة. يحتاج فريق الشراء في الإمارات إلى ورقة مقارنة منظمة تحفظ كل عرض أصلي وتظهر افتراضات التحويل لمن يعتمدون الطلب.',answer:'أكد المرجع والنطاق التجاري أولاً، ثم وحّد الكميات والعملات باستخدام مدخلات موثقة. افصل سعر المنتج والإكسسوارات والتعبئة والتسليم. علّم المبالغ الناقصة كمسائل غير محسومة لا كأصفار، وميز التقدير الداخلي للمقارنة عن مبلغ المورد الذي سيظهر فعلياً في الفاتورة.',sections:[['حدد كمية منتج قابلة للمقارنة فعلاً','سجل مرجع المورد والأبعاد وعدد القطع في العبوة ووحدة التسعير. اسأل عن حساب التغطية المفيدة للمقطع المختار وهل المساحة المعروضة تستخدم التعريف نفسه. لا تفترض أن العرض الظاهر يساوي عرض التركيب الفعلي. اختر كمية مقارنة مشتركة مرتبطة باحتياج المشروع، ثم أظهر تحويلها إلى ألواح وعبوات كاملة. أبق التقريب ظاهراً لأن شراء جزء من عبوة مغلقة ليس متاحاً دائماً. افصل سماحية القص عن تغطية المصنع؛ فهي افتراض تخطيط للمشروع وليست وسيلة لزيادة مساحة المنتج. إذا احتاج التصميمان إكسسوارات مختلفة، فأدرج الفرق في المقارنة.'],['أعلن افتراض الصرف وتاريخه','احتفظ بعملة العرض ومبلغه الأصلي دون تعديل في أعمدة المصدر. سجل في أعمدة المقارنة عملة التقرير ومصدر سعر الصرف واتجاهه وتاريخه. السعر المعبر عنه بوحدات عملة التقرير لكل وحدة من عملة المورد يختلف حسابياً عن مقلوبه؛ اكتب الاتجاه بالكلمات. هذه مقارنة شراء وليست ضماناً لسعر التسوية. اسأل الفريق المالي عن الرسوم أو ترتيبات الدفع التي تحتاج اعتباراً مستقلاً، وسجلها فقط عندما تكون معلومة. إذا انتهت صلاحية العرض قبل القرار المخطط، فاطلب التأكيد بدلاً من افتراض بقاء السعر صالحاً بلا نهاية.'],['وحّد نطاق التسليم قبل جمع الإجماليات','توضح ICC أن قواعد Incoterms تبين المهام والتكاليف والمخاطر في التسليم بين البائع والمشتري. سجل القاعدة المتفق عليها والمكان أو الميناء المحدد والإصدار لكل عرض، واطلب توضيح أي صياغة ناقصة. لا تقارن مباشرة سعراً عند نقطة تسليم بسعر يغطي نطاقاً مختلفاً. اجعل الشحن والمناولة والتأمين عند انطباقه والرسوم التي يحددها المستورد مدخلات مستقلة تدعمها معلومات حديثة. هذا الدليل لا يحسب ضرائب الإمارات ولا يحدد المعاملة الجمركية. لا تسمِّ مجموعاً جزئياً تكلفة وصول نهائية بينما تبقى رسوم أو مسؤوليات ضرورية غير محسومة.'],['احفظ إمكانية تتبع القرار عند تغير الافتراضات','احفظ عروض الموردين مع رقم مراجعة المقارنة وتاريخها. حدد الخلايا التي تمثل حقائق أكدها المورد وافتراضات المشروع والمسائل المفتوحة. أعد الحساب عند تغير كميات التعبئة أو التغطية أو افتراضات العملة أو نطاق التسليم؛ لا تعدّل الإجمالي وحده. اطلب من مراجع ثانٍ إعادة حساب تحويل واحد مستقلاً ومقارنته بالنتيجة. يجب أن يراعي قرار الشراء ملاءمة المواصفات والأدلة لا ترتيب الأسعار فقط. قبل إصدار الطلب، أكد الكمية النهائية وعملة الفاتورة وشروط الدفع وصياغة التسليم مع المورد. احفظ النسخة المقبولة لتستند مراجعة الفواتير لاحقاً إلى الأساس المتفق عليه.']],checklist:['تأكيد المنتج ووحدة البيع والتغطية الفعلية.','حفظ العملة الأصلية وتوثيق اتجاه التحويل وتاريخه.','إظهار قاعدة التسليم والموقع والتكاليف المستثناة.','مطابقة الطلب النهائي بمراجعة المقارنة المعتمدة.'],faq:[['هل نقارن سعر المتر المربع مباشرة بسعر اللوح؟','فقط بعد تأكيد تعريف تغطية اللوح وتحويل الكمية. أدرج التقريب لعبوات كاملة والإكسسوارات ذات الصلة منفصلين.'],['هل الإجمالي المحول هو ما سيخصمه البنك؟','ليس بالضرورة. إنه تقدير وفق افتراضات معلنة. تحتاج أسعار التسوية والرسوم وترتيبات الدفع تأكيداً مستقلاً من المسؤولين الماليين.']],closing:'أرسل إلى Luvie مرجع WPC وكمية المشروع وأساس التسليم المطلوب. اطلب وضوح وحدة البيع وكميات التعبئة وعملة العرض قبل مقارنة عروض طلب الإمارات.'},
{title:'ألواح PU لأوزبكستان: تسليم احتياطي الصيانة | Luvie',heading:'ألواح PU الحجرية لأوزبكستان: سلّم احتياطياً صالحاً للصيانة',description:'خطط لاحتياطي ألواح PU عبر ربط التشطيبات بالمواقع وتحديد مسؤول التخزين وسجل الصرف ومحفز إعادة الطلب.',lead:'لا تفيد ألواح PU الاحتياطية كثيراً إذا لم يعرف أحد مكانها أو الجدار الذي تطابقه. قد يترك المقاول عدة عبوات بعد التركيب، لكنها قد تجمع قطعاً كاملة غير مستخدمة ومواد تالفة وقصاصات بتشطيبات مختلفة. في مشروع أوزبكستان، التسليم المفيد هو احتياطي موثق في عهدة مسؤول محدد، مع قاعدة واضحة لصرف القطع وسجل يبقى بعد مغادرة فريق التركيب.',answer:'اتفق على نطاق الاحتياطي قبل الطلب النهائي، وافصل المخزون الصالح عن بقايا التركيب، واربط كل مرجع محفوظ بمواقعه المنفذة. سجل العهدة وإرشادات التخزين وصلاحيات الصرف. تتبع الكمية ظروف المشروع؛ لا يفرض الدليل نسبة عامة ولا يعد بتوفر التشطيب مستقبلاً.',sections:[['اختر الاحتياطي وفق احتياج الصيانة الفعلي','ناقش المواقع المنفذة واحتمال الضرر العرضي وطريقة الاستبدال العملية وعدم اليقين في التوريد المستقبلي مع فريق المشروع. قد تحتاج زاوية كثيرة الاحتكاك خطة مختلفة عن مساحة زخرفية يصعب الوصول إليها. أكد هل يتطلب الإصلاح ألواحاً كاملة أو حليات أو مكونات متوافقة أخرى. حدد الاحتياطي وفق المخطط المعتمد ووحدات تعبئة المورد، مع فصل سماحية قص التركيب عن مواد الصيانة المستقبلية المقصودة. سجل المبرر بدلاً من نسخ نسبة من مشروع آخر. يقدم ISO 55000 مبادئ عامة لإدارة الأصول؛ لا يحدد كمية احتياطي ألواح PU ولا يثبت صلاحية طريقة تركيب بعينها.'],['عرّف القطع المحفوظة قبل إخلاء الموقع','عند التسليم، عدّ الألواح الكاملة الصالحة والحليات والقصاصات المتفق على فائدتها منفصلة. افحص الحالة الظاهرة واعزل التالف بدلاً من احتسابه بديلاً جاهزاً. احفظ مرجع المورد ورمز التشطيب ومعرفات التعبئة ذات الصلة ومرجع طلب المشروع متى توفرت. أنشئ خريطة تربط المواد المحفوظة بالغرف أو مناطق الجدران التي رُكب فيها المنتج الموافق. تساعد الصور على شرح الخريطة لكنها لا تحل محل التعريف المكتوب. إذا استُخدمت تسليمات مختلفة، فاحفظ التمييز بينها حيث أمكن. لا تعد بتطابق لوني غير مرئي مستقبلاً؛ فقد تؤثر الإضاءة والتقادم واختلافات الإنتاج في مظهر البديل.'],['حدد صاحب العهدة وسجل التخزين','اتفق على مستلم المواد وموقع التخزين ومن يجيز السحب. اطلب إرشادات التخزين والمناولة الخاصة بالمنتج وانقلها لمشغل المبنى بدلاً من اختلاق حدود عامة للتكديس أو البيئة. أبق العبوات معرّفة ومحمية وفق الإرشادات المناسبة، ولا تضعها حيث قد تُرمى أثناء التنظيف المعتاد. أرفق ورقة مخزون بالكميات والحالة والموقع وتاريخ التسليم. يجب أن يقر المركّب ومستلم العهدة بالفروق بينما يستطيع كلاهما فحص المخزون. اجعل السجلات متاحة لفرق الصيانة المستقبلية دون الاعتماد على هاتف موظف شخصي أو مجموعة محادثة مؤقتة للبناء.'],['سجل الصرف وحدد القرار التالي','عند صرف قطعة، سجل المرجع والكمية والوجهة والسبب وصاحب الموافقة. سجل اكتمال الإصلاح وما إذا كانت المواد غير المستخدمة المعادة للاحتياطي لا تزال صالحة. راجع الرصيد بعد الصرف أو تعديل توزيع المبنى. اتفق على مؤشر لبحث إعادة التوريد، لكن ميزه عن التزام المورد بحفظ مخزون مطابق إلى أجل غير محدد. إذا توقف المرجع الأصلي، فاطلب تقييماً موثقاً للبديل بدلاً من خلط المنتجات بصمت. افحص المخزون الفعلي وإمكان الوصول لسجلاته في المراجعات الدورية. احتياطي صغير جيد التعريف أنفع من كومة غير مفحوصة تسمى ألواحاً احتياطية.']],checklist:['فصل مبرر كمية الاحتياطي عن سماحية التركيب.','ربط المخزون المحفوظ الصالح بمواقع التركيب.','تسجيل صاحب العهدة والموقع وإرشادات التخزين.','الاتفاق على سجل الصرف ومؤشر قرار إعادة التوريد.'],faq:[['هل يجب أن يحفظ كل مشروع النسبة نفسها؟','لا يقرر هذا الدليل نسبة موحدة. راجع المخطط وطريقة الاستبدال والمخاطر ووحدات التعبئة وعدم اليقين في التوريد مع فريق المشروع المسؤول.'],['هل تُحسب جميع القصاصات ضمن احتياطي الصيانة؟','لا. احسب فقط القطع ذات الغرض المحدد والحالة المقبولة. سجل أبعادها الصالحة منفصلة عن الألواح الكاملة.']],closing:'أرسل إلى Luvie مرجع ألواح PU الحجرية ومخطط المشروع. ناقش احتياطياً محدد الهوية للصيانة واطلب معلومات التعبئة والتعريف والتخزين قبل تسليم مشروع أوزبكستان.'}
];
guides.forEach((guide,index)=>{guide.ar=ar[index];});
const translations = JSON.parse((await import('node:fs')).readFileSync(new URL('./makeup-guides-20261108-es-pt.json', import.meta.url), 'utf8'));
for (const guide of guides) Object.assign(guide, translations[guide.file]);
